@Test
public void testCustomLock() {
    CarbonProperties.getInstance().addProperty(CarbonCommonConstants.LOCK_TYPE, CarbonCommonConstants.CARBON_LOCK_TYPE_CUSTOM);
    CarbonProperties.getInstance().addProperty(CarbonCommonConstants.LOCK_CLASS, CustomLock.class.getName());
    final List<Thread> threadList = new ArrayList<>(2);
    for (int index = 0; index < 2; index++) {
        threadList.add(new Thread() {

            @Override
            public void run() {
                ICarbonLock lock = CarbonLockFactory.getSystemLevelCarbonLockObj("root", "test");
                // do something.
                try {
                    Thread.sleep(1500L);
                } catch (InterruptedException ignore) {
                    // ignore.
                }
                lock.unlock();
            }
        });
    }
    final long startTime = System.nanoTime();
    for (Thread thread : threadList) {
        thread.start();
    }
    for (Thread thread : threadList) {
        try {
            thread.join();
        } catch (InterruptedException ignore) {
            // ignore.
        }
    }
    Assert.assertTrue(TimeUnit.MILLISECONDS.convert(System.nanoTime() - startTime, TimeUnit.NANOSECONDS) > 3000L);
}

@Test
public void testHeapMemoryReuse() {
    MemoryAllocator heapMem = new HeapMemoryAllocator();
    // The size is less than 1024 * 1024,
    // allocate new memory every time.
    MemoryBlock onheap1 = heapMem.allocate(513);
    Object obj1 = onheap1.getBaseObject();
    heapMem.free(onheap1);
    MemoryBlock onheap2 = heapMem.allocate(514);
    Assert.assertNotEquals(obj1, onheap2.getBaseObject());
    // The size is greater than 1024 * 1024,
    // reuse the previous memory which has released.
    MemoryBlock onheap3 = heapMem.allocate(1024 * 1024 + 1);
    Assert.assertEquals(onheap3.size(), 1024 * 1024 + 1);
    Object obj3 = onheap3.getBaseObject();
    heapMem.free(onheap3);
    MemoryBlock onheap4 = heapMem.allocate(1024 * 1024 + 7);
    Assert.assertEquals(onheap4.size(), 1024 * 1024 + 7);
    Assert.assertEquals(obj3, onheap4.getBaseObject());
}

@Test
public void testHeapMemoryNotPool() {
    // not pool
    CarbonProperties.getInstance().addProperty(CarbonCommonConstants.CARBON_HEAP_MEMORY_POOLING_THRESHOLD_BYTES, "-1");
    MemoryAllocator heapMem = new HeapMemoryAllocator();
    MemoryBlock onheap1 = heapMem.allocate(513);
    Object obj1 = onheap1.getBaseObject();
    heapMem.free(onheap1);
    MemoryBlock onheap2 = heapMem.allocate(514);
    Assert.assertNotEquals(obj1, onheap2.getBaseObject());
    MemoryBlock onheap3 = heapMem.allocate(1024 * 1024 + 1);
    Assert.assertEquals(onheap3.size(), 1024 * 1024 + 1);
    Object obj3 = onheap3.getBaseObject();
    heapMem.free(onheap3);
    MemoryBlock onheap4 = heapMem.allocate(1024 * 1024 + 7);
    Assert.assertEquals(onheap4.size(), 1024 * 1024 + 7);
    Assert.assertNotEquals(obj3, onheap4.getBaseObject());
}

