@Test
public void testToBytes() {
    assertTrue(ByteUtil.toBoolean(ByteUtil.toBytes(true)));
    assertFalse(ByteUtil.toBoolean(ByteUtil.toBytes(false)));
    assertEquals(Short.MAX_VALUE, ByteUtil.toShort(ByteUtil.toBytes(Short.MAX_VALUE), 0, 2));
    assertEquals((short) (Short.MAX_VALUE / 2), ByteUtil.toShort(ByteUtil.toBytes((short) (Short.MAX_VALUE / 2)), 0, 2));
    assertEquals((short) 0, ByteUtil.toShort(ByteUtil.toBytes((short) 0), 0, 2));
    assertEquals((short) (Short.MIN_VALUE / 2), ByteUtil.toShort(ByteUtil.toBytes((short) (Short.MIN_VALUE / 2)), 0, 2));
    assertEquals(Short.MIN_VALUE, ByteUtil.toShort(ByteUtil.toBytes(Short.MIN_VALUE), 0, 2));
    assertEquals(Integer.MAX_VALUE, ByteUtil.toInt(ByteUtil.toBytes(Integer.MAX_VALUE), 0, 4));
    assertEquals(Integer.MAX_VALUE / 2, ByteUtil.toInt(ByteUtil.toBytes(Integer.MAX_VALUE / 2), 0, 4));
    assertEquals(0, ByteUtil.toInt(ByteUtil.toBytes(0), 0, 4));
    assertEquals(Integer.MIN_VALUE / 2, ByteUtil.toInt(ByteUtil.toBytes(Integer.MIN_VALUE / 2), 0, 4));
    assertEquals(Integer.MIN_VALUE, ByteUtil.toInt(ByteUtil.toBytes(Integer.MIN_VALUE), 0, 4));
    assertEquals(Long.MAX_VALUE, ByteUtil.toLong(ByteUtil.toBytes(Long.MAX_VALUE), 0, 8));
    assertEquals(Long.MAX_VALUE / 2, ByteUtil.toLong(ByteUtil.toBytes(Long.MAX_VALUE / 2), 0, 8));
    assertEquals(0L, ByteUtil.toLong(ByteUtil.toBytes(0L), 0, 8));
    assertEquals(Long.MIN_VALUE / 2, ByteUtil.toLong(ByteUtil.toBytes(Long.MIN_VALUE / 2), 0, 8));
    assertEquals(Long.MIN_VALUE, ByteUtil.toLong(ByteUtil.toBytes(Long.MIN_VALUE), 0, 8));
    assertEquals(Double.MAX_VALUE, ByteUtil.toDouble(ByteUtil.toBytes(Double.MAX_VALUE), 0, 8));
    assertEquals(Double.MAX_VALUE / 2, ByteUtil.toDouble(ByteUtil.toBytes(Double.MAX_VALUE / 2), 0, 8));
    assertEquals((double) 0, ByteUtil.toDouble(ByteUtil.toBytes((double) 0), 0, 8));
    assertEquals(Double.MIN_VALUE / 2, ByteUtil.toDouble(ByteUtil.toBytes(Double.MIN_VALUE / 2), 0, 8));
    assertEquals(Double.MIN_VALUE, ByteUtil.toDouble(ByteUtil.toBytes(Double.MIN_VALUE), 0, 8));
}

