}

@Test
public void testGetBlockletIndex() throws Exception {
    long left = Long.MAX_VALUE;
    long right = 100;
    ByteBuffer buffer = ByteBuffer.allocate(8);
    buffer.putLong(left);
    buffer.flip();
    byte[] l = buffer.array().clone();
    buffer.rewind();
    buffer.putLong(right);
    buffer.flip();
    byte[] r = buffer.array().clone();
    Method method = CarbonUtil.class.getDeclaredMethod("compareMeasureData", l.getClass(), r.getClass(), org.apache.carbondata.core.metadata.datatype.DataType.class);
    method.setAccessible(true);
    int out = (int) method.invoke(method, l, r, DataTypes.LONG);
    assertEquals(1, out);
}

