@Test
public void testingLocalFileLockingByAcquiring2Locks() {
    AbsoluteTableIdentifier absoluteTableIdentifier = AbsoluteTableIdentifier.from(CarbonProperties.getInstance().getProperty("carbon.storelocation"), "databaseName", "tableName", UUID.randomUUID().toString());
    LocalFileLock localLock1 = new LocalFileLock(absoluteTableIdentifier.getTablePath(), LockUsage.METADATA_LOCK);
    Assert.assertTrue(localLock1.lock());
    LocalFileLock localLock2 = new LocalFileLock(absoluteTableIdentifier.getTablePath(), LockUsage.METADATA_LOCK);
    Assert.assertTrue(!localLock2.lock());
    Assert.assertTrue(localLock1.unlock());
    Assert.assertTrue(localLock2.lock());
    Assert.assertTrue(localLock2.unlock());
}

