@Test
public void testWriteAllPrimitive() throws IOException {
    FileUtils.deleteDirectory(new File(path));
    // Avro schema
    // Supported Primitive Datatype.
    // 1. Boolean
    // 2. Int
    // 3. long
    // 4. float -> To carbon Internally it is double.
    // 5. double
    // 6. String
    // Not Supported
    // 1.NULL Datatype
