        for (int i = 1; i <= 100000; i++) {
            writer.write(new String[] { "robot" + i, data, String.valueOf(i) });
        }
        writer.close();
    } catch (Exception ex) {
        assert (false);
    }
    // configure cache size = 4 blocklet
    CarbonProperties.getInstance().addProperty(CarbonCommonConstants.CARBON_MAX_PAGINATION_LRU_CACHE_SIZE_IN_MB, "4");
    //filter expression
    EqualToExpression equalExpression = new EqualToExpression(new ColumnExpression("name", DataTypes.STRING), new LiteralExpression("robot1", DataTypes.STRING));
    CarbonReaderBuilder carbonReaderBuilder = CarbonReader.builder(path, "_temp").withPaginationSupport().projection(new String[] { "name", "id" }).filter(equalExpression);
