    assert (paginationCarbonReader.getTotalRows() == 1);
    paginationCarbonReader.close();
    // Not Equals expression
    NotEqualsExpression notEqualsExpression = new NotEqualsExpression(new ColumnExpression("name", DataTypes.STRING), new LiteralExpression("robot1", DataTypes.STRING));
    paginationCarbonReader = (PaginationCarbonReader<Object>) carbonReaderBuilder.filter(notEqualsExpression).build();
    assert (paginationCarbonReader.getTotalRows() == 99999);
    paginationCarbonReader.close();
    FileUtils.deleteDirectory(new File(path));
}

